// Client hit handler for missile 052 (flying rock / boulder type). On impact with a large monster (MonStats2 large flag), spawns CltHitSubMissile1 via CastAttack at impact position, then calls MISSILE_CreateFlyingRockDebris using HitPar1/2/SubMissile2/3. Returns 0 immediately if target is not a large monster.
int32_t __fastcall MISSILE_CltHitFn52_MoltenBoulder(D2UnitStrc * pUnit, D2UnitStrc * pTarget) {
    int32_t nLevel;
    eD2Skills eSkill;
    int32_t nPosY;
    int32_t nPosX;
    D2UnitStrc* pOwner;
    short int nSubMissile;
    if (!pUnit) {
      return 1;
    }

    int nClassId = pUnit->nClassId;
    D2MissilesTxt* pMissileTxt = nClassId >= 0 && nClassId < sgptDataTable->nTxtMissilesSize ? sgptDataTable->pTxtMissiles + nClassId : nullptr;
    if (!pMissileTxt) {
      return 1;
    }
    if (pTarget) {
      BOOL bIsLarge;
      if (pTarget->eUnitType != UNIT_MONSTER) {
        return 0;
      }

      bIsLarge = Player::TXT_MonStats_MonStats2_GetFlagsByBitOffset(pTarget->nClassId, TXTMonStats2Field0x04DWORD_ns::large);
      if (!bIsLarge) {
        return 0;
      }
    }
    if (pMissileTxt->CltHitSubMissile1 >= 0) {
      nLevel = D2Common::Units::Missile::GetLevel(pUnit);
      eSkill = D2Common::Units::Missile::GetSkillId(pUnit);
      nPosY = Units::GetYPosFromDynamicPathUnit(pUnit);
      nPosX = Units::GetXPosFromDynamicPathUnit(pUnit);
      nSubMissile = pMissileTxt->CltHitSubMissile1;
      pOwner = Player::MISSILE_GetOwnerUnit(pUnit);
      CastAttack(pOwner, (int)nSubMissile, nPosX, nPosY, eSkill, nLevel);
    }

    MISSILE_CreateFlyingRockDebris(pUnit, pMissileTxt->cHitPar1, pMissileTxt->cHitPar2, (int)pMissileTxt->CltHitSubMissile2, (int)pMissileTxt->CltHitSubMissile3);
    return 1;
}

