        nStepCount = 2;
        if (nClassId >= 2) {
          nStepCount = nClassId;
        }

        nDelay = pMissileTxt->CltParam2 - nClassId;
        if (nDelay < 3) {
          nDelay = 3;
        }

        pTrailMissile = MISSILE_CreatePeriodicTrail(pUnit, pMissileTxt->CltParam1 + nStepCount, nDelay, eSubMissile);
