            uRandOffsetY = Archive::UNIT_GetModuloFromSeed(pSeed, nAuraRange * 2 + 1);
            nOriginY = Units::GetYPosFromDynamicPathUnit(pUnit);
            nTargetX = D2Common::Seed::GetSeed_nSeedLow(pSeed);
